    <!--Driver Code Starts-->
<html>
<head>
<!--Driver Code Ends-->

  <style>
    ul {
      list-style-type: square; 
    }
  </style>

<!--Driver Code Starts-->
</head>
<body>
  <ul>
    <li>Item 1</li>
    <li>Item 2</li>
